// Repro for prj-a26914b30e:root-cause.
// Specified behaviour: a change on `noisy` in either direction restarts the
// stability count, so a pulse of STABLE edges or fewer, high or low, never
// reaches `clean`. This test drives a 2-edge low glitch after `clean` has
// settled high, and checks that `clean` stays high.
`timescale 1ns / 1ps
module debounce_rc_repro;
    localparam integer STABLE = 4;

    reg clk = 1'b0;
    reg rst = 1'b1;
    reg noisy = 1'b0;
    wire clean;

    integer passed = 0;
    integer failed = 0;
    reg in_window = 1'b0;
    reg glitch_seen = 1'b0;
    reg [8*64-1:0] nonce;

    debounce #(.STABLE(STABLE)) dut (
        .clk(clk),
        .rst(rst),
        .noisy(noisy),
        .clean(clean)
    );

    always #5 clk = ~clk;

    // Sample clean mid-cycle (inputs change on negedge too, after this check).
    always @(negedge clk) begin
        if (in_window && clean !== 1'b1)
            glitch_seen <= 1'b1;
    end

    initial begin
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";

        // Reset.
        rst = 1'b1;
        noisy = 1'b0;
        repeat (3) @(negedge clk);
        rst = 1'b0;

        // Hold noisy high long enough for clean to follow.
        noisy = 1'b1;
        repeat (12) @(negedge clk);

        // Check 1: clean has followed a long-stable high input.
        if (clean === 1'b1) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK 1 FAILED: clean=%b after noisy held high 12 cycles", clean);
        end

        // Short low glitch: noisy low for 2 rising edges (well under STABLE).
        in_window = 1'b1;
        noisy = 1'b0;
        repeat (2) @(negedge clk);
        noisy = 1'b1;
        repeat (10) @(negedge clk);
        in_window = 1'b0;
        @(negedge clk);

        // Check 2: the glitch never reached clean.
        if (!glitch_seen) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK 2 FAILED: a 2-edge low pulse on noisy reached clean (STABLE=%0d)", STABLE);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===

{"uncertainty": 0.15, "outcome": "rtl_bug", "artifacts": [{"kind": "root_cause_analysis", "title": "Root cause: debounce restarts its stability count on rising edges of noisy only", "summary": "Conclusion: rtl_bug in debounce_rise_only_restart.v [artifact:prj-a26914b30e.design-under-investigation.a1]. This serves requirement [requirement:req-19189b08df]. Triage reported a failure in which 1 of 1 checks failed [evidence:prj-a26914b30e.triage.e2]. VeriTriage classified it as unknown_failure at 30% confidence, with 'Likely RTL bug' as its top hypothesis [evidence:prj-a26914b30e.triage.e1]. I treated that hypothesis as one candidate to test, not as the answer.\n\nDefect (from reading the source): the count resets only under `if (noisy && !prev) cnt <= 4'd0;`. A falling edge does not reset it. The module header states the opposite: 'A change on noisy, in either direction, restarts the count, so a pulse of STABLE edges or fewer, high or low, never reaches clean.'\n\nCausality: once clean is high and noisy has been stable, cnt saturates at STABLE-1. The step-by-step is:\n- First posedge after noisy drops: noisy != prev, so clean is not updated, and cnt stays at STABLE-1 because it is not reset.\n- Second posedge: noisy == prev == 0 and cnt == STABLE-1, so clean <= 0.\n- Result: a 2-edge low glitch reaches clean.\n\nIncorrectness: the restart condition must be any change (noisy != prev), not only a rise. As written, no low pulse after a long high is filtered, whatever its length.\n\nCompeting hypotheses, ranked, with the evidence that would refute each:\n1. rtl_bug (supported). Refuted if the clean debouncer also let a 2-edge low pulse through, or if the source reset cnt on falling edges. It does not: the reset is guarded by `noisy && !prev`.\n2. testbench_bug (rejected). The repro's expected value comes from the specification text in the header, not from RTL output. I traced the repro by hand against an RTL whose restart condition is `noisy != prev`:\n   - Check 1 passes: clean goes high within 12 cycles.\n   - Check 2 passes: the first low edge sets cnt to 0, the second sets it to 1, and the rising edge sets it to 0 again, so clean never drops.\n   Refuted only if the platform's clean-RTL run of the repro fails.\n3. infrastructure (rejected). The triage failure reached $finish and reported a counted check failure [evidence:prj-a26914b30e.triage.e2]. That is a deterministic behavioural result, not a build or tool fault. Refuted if a clean rebuild changed the result.\n4. spec_ambiguity (rejected). The clause the check relies on explicitly says 'in either direction' and 'high or low'. Refuted only if the governing specification outside this file says otherwise; I was given none.\n\nThe RTL is approved with an independent review recorded [evidence:prj-a26914b30e.design-under-investigation.e1]. That review covers the fixture, not this diagnosis.\n\nRecommended fix (not applied): change the reset condition to `if (noisy != prev) cnt <= 4'd0;`. Then add the repro to regression, plus an assertion that clean changes only after STABLE stable edges."}], "files": [{"path": "debounce_rc_repro.v", "kind": "testbench", "title": "Self-checking repro: short low glitch must not reach clean", "summary": "Self-checking repro for the debouncer [artifact:prj-a26914b30e.design-under-investigation.a1], serving [requirement:req-19189b08df].\n- Check 1: holds noisy high and checks that clean follows.\n- Check 2: drives a 2-edge low glitch and checks that clean stays high, as the header specification requires.\n- Ends with one NIRMAAN-SIM verdict line carrying the nonce, printed just before $finish.\n- Expected outcome: check 2 should fail on the rise-only-restart RTL and pass on an RTL that restarts the count on any change.", "entry": "debounce_rc_repro"}], "tool_runs": [], "claims": ["The hand trace predicts that debounce_rc_repro fails check 2 on the approved RTL: clean drops to 0 two edges after the low glitch begins.", "The hand trace predicts that debounce_rc_repro passes both checks on an RTL using `noisy != prev` as the restart condition.", "No simulation was run by me; the reproduction result depends on the platform's simulator.run with expect=fail."], "escalation": null, "notes": "Attempt 1 was refused for listing run IDs in tool_runs. This attempt leaves tool_runs empty and cites the triage results through their evidence tokens only. The testbench content is unchanged from attempt 1, because its logic was not the cause of the refusal. Independent review of this analysis still has to be recorded by a reviewer other than me."}

